#include "window.h"
#include <algorithm>

QJsonObject englishDictionary(){
    QFile file(":/dictionary/english.json");if(!file.open(QIODevice::ReadOnly))return {};
    auto rows=QJsonDocument::fromJson(file.readAll()).array();QJsonObject out;int order=0;
    for(auto value:rows){auto row=value.toObject();QString chinese=row["chinese"].toString();out.insert(row["name"].toString(),QJsonObject{{"chinese",chinese},{"aliases",QJsonArray{chinese}},{"order",order++}});}return out;
}
QString dictionaryProfilesFile(){return dictionaryFile()+".profiles.json";}
static bool writeProfiles(QJsonArray profiles,QString active){QSaveFile file(dictionaryProfilesFile());return file.open(QIODevice::WriteOnly)&&file.write(QJsonDocument(QJsonObject{{"version",1},{"active",active},{"profiles",profiles}}).toJson())>=0&&file.commit();}
void initializeEnglishDictionary(Window& window){
    QFile file(dictionaryProfilesFile());if(file.open(QIODevice::ReadOnly)){auto root=QJsonDocument::fromJson(file.readAll()).object();auto profiles=root["profiles"].toArray();bool valid=root["version"].toInt()==1&&!profiles.isEmpty();QSet<QString> ids,names;
        for(auto value:profiles){auto p=value.toObject();QString id=p["id"].toString(),name=p["name"].toString().trimmed();if(id.isEmpty()||name.isEmpty()||ids.contains(id)||names.contains(name.toCaseFolded())||!p["dictionary"].isObject())valid=false;ids.insert(id);names.insert(name.toCaseFolded());}
        if(valid){window.dictionaryProfiles=profiles;window.dictionaryProfile=root["active"].toString();if(!ids.contains(window.dictionaryProfile))window.dictionaryProfile=profiles.first().toObject()["id"].toString();for(auto value:profiles){auto p=value.toObject();if(p["id"].toString()==window.dictionaryProfile){window.dictionary=p["dictionary"].toObject();window.dictionaryMatchMode=p["matchMode"].toString("contains");}}return;}
    }
    // Keep the previous dictionary intact. Upgrade it to an editable English profile once.
    window.dictionaryProfiles=QJsonArray{QJsonObject{{"id","english"},{"name",QStringLiteral("英语")},{"matchMode","exact"},{"dictionary",window.dictionary.isEmpty()?englishDictionary():window.dictionary}}};window.dictionaryProfile="english";window.dictionaryMatchMode="exact";window.dictionary=window.dictionaryProfiles.first().toObject()["dictionary"].toObject();
    if(!QFile::exists(dictionaryProfilesFile()))writeProfiles(window.dictionaryProfiles,window.dictionaryProfile);
}
static QStringList aliasesFor(QString text){QStringList aliases;for(auto alias:text.split(QRegularExpression("[、,，;；\\n]"),Qt::SkipEmptyParts)){alias=alias.trimmed();if(!alias.isEmpty()&&!aliases.contains(alias))aliases.append(alias);}return aliases;}
QString dictionaryConflict(const QJsonObject& dictionary){
    QHash<QString,QString> owners;for(auto it=dictionary.begin();it!=dictionary.end();++it){QString output=it.key().trimmed();if(output.isEmpty())return ui("改名结果不能为空");QStringList matches{output,it.value().toObject()["chinese"].toString()};for(auto alias:it.value().toObject()["aliases"].toArray())matches.append(alias.toString());for(auto match:matches){match=match.trimmed().toCaseFolded();if(match.isEmpty())continue;if(owners.contains(match)&&owners[match]!=it.key())return ui("匹配冲突：%1（%2 / %3）").arg(match,owners[match],it.key());owners.insert(match,it.key());}}return {};
}
QString dictionaryName(QString source,const QJsonObject& dictionary,QString mode){QString exact,partial;int length=0;bool ambiguousExact=false,ambiguousPartial=false;for(auto it=dictionary.begin();it!=dictionary.end();++it){QStringList aliases{it.key(),it.value().toObject()["chinese"].toString()};for(auto a:it.value().toObject()["aliases"].toArray())aliases.append(a.toString());for(auto alias:aliases){alias=alias.trimmed();if(alias.isEmpty())continue;if(alias.compare(source.trimmed(),Qt::CaseInsensitive)==0){if(!exact.isEmpty()&&exact!=it.key())ambiguousExact=true;exact=it.key();}if(mode=="contains"&&source.contains(alias,Qt::CaseInsensitive)){if(alias.size()>length){partial=it.key();length=alias.size();ambiguousPartial=false;}else if(alias.size()==length&&partial!=it.key())ambiguousPartial=true;}}}if(!exact.isEmpty())return ambiguousExact?source:exact;return !partial.isEmpty()&&!ambiguousPartial?partial:source;}
QJsonObject dictionaryExport(QString name,const QJsonObject& dictionary,QString mode){return {{"format","psd-naming-dictionary"},{"version",1},{"name",name},{"dictionary",dictionary},{"matchMode",mode}};}
bool dictionaryImport(const QJsonObject& root,QString& name,QJsonObject& dictionary,QString& error,QString* mode){
    QString importedMode=root["matchMode"].toString("contains");if(importedMode!="exact"&&importedMode!="contains"){error=ui("匹配方式无效");return false;}if(mode)*mode=importedMode;
    bool envelope=root.contains("format")||root.contains("dictionary");if(envelope){if(root["format"].toString()!="psd-naming-dictionary"||root["version"].toInt()!=1||!root["dictionary"].isObject()){error=ui("方案文件格式无效");return false;}name=root["name"].toString().trimmed();dictionary=root["dictionary"].toObject();}else dictionary=root;
    for(auto it=dictionary.begin();it!=dictionary.end();++it){if(!it.value().isObject()){error=ui("词库条目格式无效");return false;}auto entry=it.value().toObject();if(entry.contains("chinese")&&!entry["chinese"].isString()){error=ui("标准名称格式无效");return false;}if(entry.contains("aliases")&&!entry["aliases"].isArray()){error=ui("匹配名称格式无效");return false;}for(auto alias:entry["aliases"].toArray())if(!alias.isString()){error=ui("匹配名称格式无效");return false;}}
    error=dictionaryConflict(dictionary);return error.isEmpty();
}
