    auto tools=new QHBoxLayout;auto scheme=new QComboBox(&dialog);scheme->setObjectName("dictionaryScheme");scheme->setMinimumWidth(180);tools->addWidget(new QLabel(ui("方案"),&dialog));tools->addWidget(scheme,1);
    auto tool=[&](QString title,QString id){auto b=new QPushButton(title,&dialog);b->setObjectName(id);tools->addWidget(b);return b;};auto create=tool(ui("新建"),"newScheme"),copy=tool(ui("复制"),"copyScheme"),rename=tool(ui("重命名"),"renameScheme"),erase=tool(ui("删除"),"deleteScheme");layout->addLayout(tools);auto matchingTools=new QHBoxLayout;auto mode=new QComboBox(&dialog);mode->setObjectName("dictionaryMatchMode");mode->addItem(ui("完全匹配"),"exact");mode->addItem(ui("包含匹配"),"contains");matchingTools->addWidget(new QLabel(ui("匹配方式"),&dialog));matchingTools->addWidget(mode);auto preview=new QPushButton(ui("预览改名"),&dialog);preview->setObjectName("previewDictionary");matchingTools->addWidget(preview);matchingTools->addStretch();layout->addLayout(matchingTools);
    auto rowTools=new QHBoxLayout;auto search=new QLineEdit(&dialog);search->setObjectName("dictionarySearch");search->setPlaceholderText(ui("搜索"));rowTools->addWidget(search,1);auto importButton=new QPushButton(ui("导入"),&dialog),exportButton=new QPushButton(ui("导出"),&dialog),add=new QPushButton(ui("新增条目"),&dialog),remove=new QPushButton(ui("删除条目"),&dialog);importButton->setObjectName("importScheme");exportButton->setObjectName("exportScheme");rowTools->addWidget(importButton);rowTools->addWidget(exportButton);rowTools->addWidget(add);rowTools->addWidget(remove);layout->addLayout(rowTools);
    auto table=new QTableWidget(&dialog);table->setObjectName("dictionaryTable");table->setColumnCount(3);table->setHorizontalHeaderLabels({ui("标准名称"),ui("改名结果"),ui("匹配名称")});table->setSelectionBehavior(QAbstractItemView::SelectRows);table->setSelectionMode(QAbstractItemView::ExtendedSelection);table->setEditTriggers(QAbstractItemView::DoubleClicked|QAbstractItemView::EditKeyPressed);table->horizontalHeader()->setSectionResizeMode(2,QHeaderView::Stretch);table->setColumnWidth(0,180);table->setColumnWidth(1,210);table->verticalHeader()->setDefaultSectionSize(34);table->setAlternatingRowColors(true);layout->addWidget(table,1);
