    auto filter=[&]{QString query=search->text().trimmed();for(int row=0;row<table->rowCount();++row){bool matches=query.isEmpty();for(int col=0;col<3;++col)if(auto item=table->item(row,col))matches|=item->text().contains(query,Qt::CaseInsensitive);table->setRowHidden(row,!matches);}};
    auto populate=[&]{mode->setCurrentIndex(profiles[profileIndex()].toObject()["matchMode"].toString("contains")=="exact"?0:1);filling=true;QSignalBlocker blocker(table);table->setRowCount(0);auto dictionary=profiles[profileIndex()].toObject()["dictionary"].toObject();auto keys=dictionary.keys();std::stable_sort(keys.begin(),keys.end(),[&](QString a,QString b){return dictionary[a].toObject()["order"].toInt(100000)<dictionary[b].toObject()["order"].toInt(100000);});for(auto key:keys){auto entry=dictionary[key].toObject();QStringList aliases;for(auto value:entry["aliases"].toArray())aliases.append(value.toString());QString standard=entry["chinese"].toString();if(standard.isEmpty()&&!aliases.isEmpty())standard=aliases.first();aliases.removeAll(standard);if(!aliases.contains(key)&&key!=standard)aliases.append(key);int row=table->rowCount();table->insertRow(row);table->setItem(row,0,new QTableWidgetItem(standard));table->setItem(row,1,new QTableWidgetItem(key));table->setItem(row,2,new QTableWidgetItem(aliases.join(QStringLiteral("、"))));}filling=false;QJsonObject ignored;readTable(ignored);filter();};
